        ("Khi một vận động viên nhảy dù bung dù trên không trung, chiếc dù xòe rộng giúp giảm tốc độ rơi chủ yếu nhờ tác dụng của lực nào?", ["Lực cản của không khí tác dụng lên tán dù", "Lực hút của Mặt Trời", "Lực từ trường Trái Đất", "Lực đẩy Ac-si-met của gió biển"], 0, "Vật chất & Năng lượng", "medium", 5, "Tán dù có diện tích tiếp xúc rất lớn tạo ra lực cản không khí mạnh hướng lên, hãm bớt tốc độ rơi tự do."),
        ("Để tách những chiếc đinh sắt bị lẫn vào trong một thùng chứa đầy mùn cưa, cách làm nào nhanh và thông minh nhất?", ["Dùng một thanh nam châm mạnh rà quét trên mặt mùn cưa", "Dùng nhíp gắp từng chiếc đinh", "Đổ nước vào để mùn cưa chìm xuống", "Đốt cháy cả thùng mùn cưa"], 0, "Vật chất & Năng lượng", "easy", 4, "Nam châm hút sắt nhưng không hút mùn cưa gỗ, giúp phân tách hỗn hợp kim loại cực kỳ nhanh chóng."),
        ("Vào ngày trời nồm ẩm ở miền Bắc, tại sao sàn nhà lát gạch men thường bị đọng nhiều giọt nước trơn trượt?", ["Không khí ẩm gặp sàn nhà lạnh ngưng tụ thành giọt nước", "Nước từ lòng đất ngấm ngược xuyên qua gạch men", "Gạch men tự tiết ra nước", "Có người làm đổ xô nước ra sàn"], 0, "Vật chất & Năng lượng", "hard", 5, "Sàn nhà có quán tính nhiệt giữ lạnh lâu; gió nồm mang hơi nước ấm thổi vào gặp lạnh ngưng tụ thành nước lỏng."),
        ("Khi đi trên tuyết lầy lội, người ta thường đeo thêm tấm vợt tuyết bản rất rộng dưới đế giày để làm gì?", ["Tăng diện tích tiếp xúc để giảm áp suất nén, tránh bị lún sâu vào tuyết", "Làm cho đôi chân nặng hơn để bước chắc", "Để trượt tuyết nhanh như xe máy", "Để bảo vệ giày không bị mòn đế"], 0, "Vật chất & Năng lượng", "hard", 5, "Áp suất bằng áp lực chia cho diện tích; tăng diện tích tiếp xúc giúp giảm áp suất lên bề mặt tuyết mềm."),

        # Trái Đất & Vũ trụ (15 câu)
        ("Trái Đất tự quay quanh một trục tưởng tượng theo hướng nào, khiến ta thấy Mặt Trời mọc ở hướng Đông và lặn ở hướng Tây?", ["Tự quay từ Tây sang Đông", "Tự quay từ Đông sang Tây", "Tự quay từ Bắc xuống Nam", "Tự quay từ Nam lên Bắc"], 0, "Trái Đất & Bầu trời", "medium", 4, "Chuyển động tự quay từ Tây sang Đông của Trái Đất tạo ra chuyển động biểu kiến ngược lại của Mặt Trời."),
        ("Vì sao ở vùng xích đạo Trái Đất quanh năm luôn ấm áp và nóng, trong khi hai cực lại phủ băng giá vĩnh cửu?", ["Vùng xích đạo nhận được góc chiếu tia nắng mặt trời thẳng đứng hơn", "Xích đạo ở gần Mặt Trời hơn 1 triệu km", "Ở hai cực không có không khí", "Ở cực không bao giờ có ban ngày"], 0, "Trái Đất & Bầu trời", "hard", 5, "Tia nắng mặt trời chiếu gần vuông góc xuống xích đạo mang năng lượng tập trung cao; ở vùng cực tia nắng bị chiếu xiên vát."),
        ("Hiện tượng các mùa (Xuân, Hạ, Thu, Đông) trên Trái Đất được hình thành chủ yếu do nguyên nhân nào kết hợp lại?", ["Trái Đất chuyển động quanh Mặt Trời với trục nghiêng không đổi", "Khoảng cách giữa Trái Đất và Mặt Trời thay đổi liên tục", "Mặt Trời bị mờ đi theo chu kỳ", "Mặt Trăng chắn ánh sáng theo mùa"], 0, "Trái Đất & Bầu trời", "hard", 5, "Trục nghiêng 23.5 độ không đổi phương khi quay quanh Mặt Trời làm luân phiên hai bán cầu đón nhận nhiệt lượng khác nhau."),
        ("Nếu một nhà du hành vũ trụ đứng trên bề mặt Mặt Trăng và nhìn lên bầu trời vào ban ngày, bầu trời sẽ có màu gì?", ["Bầu trời có màu đen tối đen chứa đầy sao", "Bầu trời màu xanh lam như ở Trái Đất", "Bầu trời màu đỏ rực", "Bầu trời màu trắng xóa"], 0, "Trái Đất & Bầu trời", "hard", 5, "Mặt Trăng không có khí quyển nên không có hiện tượng tán xạ ánh sáng, bầu trời luôn mang một màu đen thẳm."),
        ("Khí quyển của Trái Đất giữ vai trò như một tấm lá chắn bảo vệ sự sống vì lý do nào sau đây?", ["Ngăn chặn tia cực tím độc hại và đốt cháy hầu hết thiên thạch nhỏ", "Ngăn không cho người bay ra ngoài vũ trụ", "Làm cho Trái Đất luôn tối tăm", "Tạo ra vàng bạc trong đất"], 0, "Trái Đất & Bầu trời", "medium", 5, "Tầng ozon lọc tia UV tử ngoại, ma sát khí quyển làm bốc cháy các mảnh thiên thạch trước khi chạm đất."),
        ("Khi xảy ra hiện tượng Nhật thực toàn phần, thiên thể nào nằm ở vị trí chính giữa thẳng hàng?", ["Mặt Trăng nằm giữa Mặt Trời và Trái Đất", "Trái Đất nằm giữa Mặt Trời và Mặt Trăng", "Mặt Trời nằm giữa Trái Đất và Mặt Trăng", "Sao Hỏa nằm giữa Mặt Trời và Trái Đất"], 0, "Trái Đất & Bầu trời", "medium", 5, "Mặt Trăng đi vào giữa đường thẳng nối Trái Đất và Mặt Trời, che khuất một phần hoặc toàn bộ đĩa Mặt Trời."),
        ("Khi xảy ra hiện tượng Nguyệt thực, thiên thể nào đóng vai trò chắn ánh sáng mặt trời chiếu vào Mặt Trăng?", ["Trái Đất chắn ánh sáng", "Mặt Trời tự tắt bóng", "Sao Kim chắn bóng", "Mây bão che bóng"], 0, "Trái Đất & Bầu trời", "medium", 5, "Trái Đất nằm giữa Mặt Trời và Mặt Trăng, bóng tối của Trái Đất trùm lên bề mặt của Mặt Trăng."),
        ("Một người cân nặng 60 kg trên Trái Đất. Khi lên Mặt Trăng, trọng lượng của người đó sẽ thay đổi như thế nào?", ["Giảm xuống chỉ còn khoảng 10 kg (bằng 1/6)", "Tăng vọt lên gấp 10 lần", "Bằng 0 kg hoàn toàn", "Vẫn giữ nguyên 60 kg trọng lượng"], 0, "Trái Đất & Bầu trời", "hard", 5, "Lực hấp dẫn trên Mặt Trăng chỉ bằng khoảng 1/6 so với Trái Đất do khối lượng Mặt Trăng nhỏ hơn nhiều."),
        ("Các hóa thạch vỏ ốc và xương cá cổ đại được phát hiện trên đỉnh núi cao Himalaya chứng minh điều gì về lịch sử Trái Đất?", ["Khu vực núi cao đó từng là đáy biển sâu hàng triệu năm trước", "Chim cổ đại mang cá lên đỉnh núi ăn", "Nước lũ từng ngập cao hơn đỉnh mây", "Người nguyên thủy chôn cá trên đỉnh núi"], 0, "Trái Đất & Bầu trời", "hard", 5, "Sự va chạm của các mảng kiến tạo vỏ Trái Đất đã đẩy lớp vỏ đáy đại dương cổ xưa trồi lên thành dãy núi Himalaya vĩ đại."),
        ("Tài nguyên nước ngọt trên Trái Đất tồn tại nhiều nhất dưới dạng nào sau đây?", ["Băng tuyết vĩnh cửu ở hai vùng cực và đỉnh núi băng sơn", "Nước trong các dòng sông suối lộ thiên", "Nước uống trong chai lọ", "Hơi nước trong các đám mây"], 0, "Trái Đất & Bầu trời", "hard", 5, "Khoảng gần 70% lượng nước ngọt toàn cầu đang bị đóng băng ở Nam Cực, Bắc Cực và đảo Greenland."),
        ("Động đất sinh ra do nguyên nhân tự nhiên chủ yếu nào dưới lòng đất?", ["Sự dịch chuyển và va chạm của các mảng kiến tạo vỏ Trái Đất", "Do gió bão thổi quá mạnh trên mặt đất", "Do các dòng sông ngầm chảy xiết", "Do sấm sét đánh vào lòng đất"], 0, "Trái Đất & Bầu trời", "medium", 4, "Năng lượng tích tụ ở các đới đứt gãy giữa các mảng thạch quyển giải phóng đột ngột tạo ra các đợt sóng địa chấn."),
        ("Vòng tuần hoàn của nước trong tự nhiên bao gồm những quá trình liên tục nào?", ["Bốc hơi, ngưng tụ thành mây, mưa rơi và chảy về biển hồ", "Đóng băng và tan chảy vĩnh viễn", "Nước chìm vào tâm Trái Đất biến mất", "Nước bay ra ngoài vũ trụ"], 0, "Trái Đất & Bầu trời", "easy", 4, "Nước bốc hơi nhờ nhiệt mặt trời, lên cao ngưng tụ thành hạt mây, gặp lạnh rơi thành mưa tuần hoàn khép kín."),
        ("Tại sao sao Kim (Kim tinh) lại là hành tinh nóng nhất trong Hệ Mặt Trời dù sao Thủy ở gần Mặt Trời hơn?", ["Bầu khí quyển dày đặc khí CO2 giữ nhiệt (hiệu ứng nhà kính cực mạnh)", "Sao Kim có ngọn núi lửa cao 100 km", "Sao Kim tự phát ra bức xạ hạt nhân", "Sao Kim có màu vàng như lửa"], 0, "Trái Đất & Bầu trời", "hard", 5, "Khí quyển chứa tới hơn 96% CO2 giữ nhiệt khổng lồ làm bề mặt sao Kim bị nung nóng tới gần 470°C."),
        ("Tại sao ở trên đỉnh núi cao, không khí loãng hơn làm cho việc đun sôi nước diễn ra ở nhiệt độ như thế nào so với mực nước biển?", ["Nước sôi ở nhiệt độ thấp hơn 100°C", "Nước sôi ở nhiệt độ cao hơn 150°C", "Nước không bao giờ sôi được", "Nước sôi đúng 100°C không đổi"], 0, "Trái Đất & Bầu trời", "hard", 5, "Áp suất khí quyển giảm dần theo độ cao; áp suất thấp làm điểm sôi của nước giảm xuống dưới 100°C."),
        ("Thời gian Trái Đất hoàn thành một vòng quay trọn vẹn quanh Mặt Trời là bao lâu?", ["Khoảng 365 ngày và 6 giờ (1 năm thiên văn)", "Đúng tròn 30 ngày", "Khoảng 24 giờ", "Khoảng 10 năm"], 0, "Trái Đất & Bầu trời", "easy", 4, "Một chu kỳ quay quanh Mặt Trời kéo dài 365.25 ngày; phần 6 giờ dôi ra tích lũy 4 năm tạo thành năm nhuận 366 ngày."),

        # Sinh thái & Đời sống sinh vật (10 câu)
        ("Trong một chuỗi thức ăn trên đồng cỏ: Cỏ -> Cào cào -> Ếch đồng -> Rắn. Nếu số lượng loài ếch đồng bị săn bắt cạn kiệt, điều gì sẽ xảy ra trước tiên?", ["Số lượng cào cào sẽ sinh sôi tăng vọt, phá hoại mùa màng", "Số lượng rắn sẽ tăng vọt bất ngờ", "Cỏ trên đồng sẽ tốt tươi hơn", "Chuỗi thức ăn không hề bị ảnh hưởng"], 0, "Thực vật & Động vật", "medium", 4, "Mất đi động vật ăn thịt trung gian (ếch), con mồi của chúng (cào cào) mất kiểm soát số lượng bùng nổ dân số."),
        ("Loài cá voi và cá heo sống dưới nước cả đời, nhưng tại sao chúng lại phải thường xuyên ngoi đầu lên mặt nước?", ["Để thở hít khí oxy vào phổi vì chúng là động vật có vú", "Để ngắm nhìn bầu trời và Mặt Trời", "Để bắt các loài chim biển bay thấp", "Để phơi nắng cho ấm vây"], 0, "Thực vật & Động vật", "easy", 4, "Cá voi hô hấp bằng phổi như con người, lỗ thở trên đỉnh đầu giúp chúng lấy oxy không khí dễ dàng khi nổi lên."),
        ("Mối quan hệ cộng sinh nổi tiếng giữa chú cá hề nhỏ và hải quỳ độc ở rạn san hô mang lại lợi ích gì cho cá hề?", ["Xúc tu độc của hải quỳ bảo vệ cá hề khỏi kẻ thù săn mồi lớn", "Hải quỳ cho cá hề uống sữa", "Cá hề dùng hải quỳ để ngủ quên mùa đông", "Hải quỳ giúp cá hề bay lên khỏi nước"], 0, "Thực vật & Động vật", "medium", 4, "Cá hề có lớp chất nhầy đặc biệt miễn dịch nọc độc của hải quỳ, mượn xúc tu độc làm pháo đài trú ngụ an toàn."),
        ("Tại sao thân cây rau muống hoặc cây sen sống ngập trong nước lại có những khoang rỗng xốp bên trong thân?", ["Chứa khí oxy để hô hấp và giúp thân cây nổi nhẹ", "Để tích trữ nước ngọt dự phòng", "Để thu hút cá đến đẻ trứng", "Do thân cây bị sâu đục khoét"], 0, "Thực vật & Động vật", "medium", 4, "Các ống khí rỗng vận chuyển không khí từ lá trên mặt nước xuống nuôi rễ và giúp cây nổi dập dềnh."),
        ("Vào mùa thu, tại sao lá của nhiều loài cây rụng lá ôn đới chuyển từ màu xanh sang màu vàng, cam hoặc đỏ thắm?", ["Chất diệp lục bị phân hủy, để lộ các sắc tố màu khác", "Do lá cây bị bụi bẩn bám vào", "Do cây bị chết khô hoàn toàn", "Do cây hút nước có pha màu đỏ từ đất"], 0, "Thực vật & Động vật", "hard", 5, "Mùa thu ít ánh sáng và lạnh làm diệp lục tố phân rã nhanh, bộc lộ các sắc tố carotenoid và anthocyanin sẵn có."),
        ("Loài nấm trong tự nhiên không có chất diệp lục, vậy chúng lấy chất dinh dưỡng bằng cách nào để sinh sống?", ["Hấp thụ chất dinh dưỡng bằng cách phân hủy xác hữu cơ mục nát", "Tự quang hợp từ ánh trăng đêm", "Hút nhiệt lượng từ không khí", "Nuốt chửng các con côn trùng sống"], 0, "Thực vật & Động vật", "medium", 4, "Nấm là sinh vật dị dưỡng, đóng vai trò phân giải cực kỳ quan trọng giúp làm sạch vật chất hữu cơ trong tự nhiên."),
        ("Tại sao loài sâu bướm lại ăn lá cây rất nhiều và phàm ăn gấp nhiều lần so với khi đã hóa thành bướm trưởng thành?", ["Tích lũy tối đa năng lượng cho giai đoạn hóa nhộng biến thái", "Vì sâu bướm phải nuôi con non", "Vì lá cây làm mát cơ thể sâu", "Vì sâu bướm không biết no"], 0, "Thực vật & Động vật", "medium", 4, "Giai đoạn ấu trùng cần lượng protein và mỡ khổng lồ để tạo kén và tái tổ chức mô cơ thể thành bướm hoàn chỉnh."),
        ("Cây bắt mồi (như cây nắp ấm, cây bẫy kẹp) thường sống ở vùng đất nghèo dinh dưỡng nào khiến chúng phải bẫy côn trùng?", ["Đất đầm lầy chua nghèo hợp chất Nitơ (đạm)", "Đất cát phù sa màu mỡ", "Đất đỏ bazan giàu dinh dưỡng", "Đất ngập mặn ven biển"], 0, "Thực vật & Động vật", "hard", 5, "Đất đầm lầy thiếu đạm nghiêm trọng; việc tiêu hóa côn trùng cung cấp lượng nitơ thiết yếu cho cây sống sót."),
