    # Xử lý gán ID, xáo trộn options, sinh đúng cấu trúc chuẩn
    raw_list = batch1 + batch2
    for idx, item in enumerate(raw_list):
        q_text, opts, correct_idx, topic, difficulty, grade, explain = item
        qid = f"IK{idx+1:03d}"
        
        # Tạo bản sao options và xáo trộn vị trí đáp án đúng ngẫu nhiên
        correct_answer = opts[correct_idx]
        shuffled_opts = list(opts)
        random.seed(idx + 300)
        random.shuffle(shuffled_opts)
        new_correct_idx = shuffled_opts.index(correct_answer)
        ans_letter = ['A', 'B', 'C', 'D'][new_correct_idx]
        diff_val = 1 if difficulty == 'easy' else (2 if difficulty == 'medium' else 3)
        
        q_obj = {
            "id": qid,
            "q": q_text,
            "question": q_text,
            "options": shuffled_opts,
            "a": shuffled_opts[0],
            "b": shuffled_opts[1],
            "c": shuffled_opts[2],
            "d": shuffled_opts[3],
            "correctIndex": new_correct_idx,
            "ans": ans_letter,
            "source": SOURCE_NAME,
            "topic": topic,
            "difficulty": difficulty,
            "diff": diff_val,
            "grade": grade,
            "explain": explain,
            "img": ""
        }
        questions.append(q_obj)

    return questions

